    "type": "object",
    "properties": {
        "groupingParam": {
            "description": "Container for information about a CBSD membership group.",
            "type": "array",
            "items": {
                "type": "object",
                "required": [
                    "groupType",
                    "groupId"
                ],
                "properties": {
                    "groupType": {
                        "enum": [
                            "INTERFERENCE_COORDINATION"
                        ],
                        "description": "Type of the group"
                    },
                    "groupId": {
                        "type": "string",
                        "maxLength": 128,
                        "description": "ID of the group"
                    }
                }
            }
        },
        "airInterface": {
            "type": "object",
            "description": "Air interface parameter for a CBSD",
            "required": [
                "radioTechnology"
            ],
            "properties": {
                "radioTechnology": {
                    "enum": [
                        "E_UTRA",
                        "CAMBIUM_NETWORKS"
                    ],
                    "description": "Which PHY radio technology is used by the device in the 3.5GHz band"
                }
            }
        }
    }
}

